    cguWelcomeIntro: "Welcome to Troco! To ensure a safe, fair, and welcoming platform, please review and approve the operating rules below.",
    pillar1Title: "1 Hour = 1 Troco Token",
    pillar1Desc: "The fundamental rule of Troco is based on equal shared time. One hour of help or training always equals 1 Troco Token, ensuring a fair and decentralized collaborative economy.",
    pillar2Title: "Lending Security & Deposits",
    pillar2Desc: "For any equipment loan, a security deposit pre-authorization can be required without immediate charge, ensuring tools are returned in perfect condition.",
    pillar3Title: "Zero Tolerance for Fraud & Scams",
    pillar3Desc: "Strictly prohibited: prepaid vouchers (Transcash, Neosurf), external wire requests (Western Union), plaintext bank details, illegal content, and hate speech.",
    pillar4Title: "Moderation & Sanctions",
    pillar4Desc: "Any breach of community rules may result in temporary suspension, Shadow-Ban (automatic hiding of ads), or permanent account termination.",
    pillar5Title: "GDPR & Data Protection",
    pillar5Desc: "Your personal data is encrypted (256-bit SSL/TLS), never sold to third parties, and you hold full rights of access, portability, and complete erasure at any time.",
    pillar6Title: "Courtesy & Mutual Respect",
    pillar6Desc: "Swaps, video conferences, and chats must take place in a supportive, punctual, and respectful atmosphere respecting everyone's privacy.",
    cguArt1Title: "Article 1 — Purpose & Definition of the Platform",
    cguArt1Desc: "Troco is a digital community intermediation platform enabling skills swaps, peer-to-peer equipment lending, and service exchanges based on the time unit 'Troco Token' or mutually agreed terms.",
    cguArt2Title: "Article 2 — Account & Information Accuracy",
    cguArt2Desc: "The user agrees to provide accurate information during registration, keep their profile up-to-date, and create only one account per individual.",
    cguArt3Title: "Article 3 — Time Swap Rules & Monetization",
    cguArt3Desc: "The Troco Token represents 1 hour of service or lessons. Token purchases or visibility boosts are final and non-refundable in accordance with applicable consumer regulations.",
    cguArt4Title: "Article 4 — Security Deposits & Lending Liability",
    cguArt4Desc: "Deposits requested for equipment loans constitute a pre-authorized financial guarantee. In the event of non-return or verified damage, the amount may be debited following review by the Troco mediation team.",
