    cguConsentTitle: "Términos y Condiciones y RGPD",
    cguConsentSubtitle: "Marco legal y compromiso comunitario",
    cguSection1Title: "1. Plataforma de intermediación técnica",
    cguSection1Desc: "Troco proporciona una infraestructura de software que permite a los usuarios publicar anuncios, intercambiar servicios y comunicarse. Troco no forma parte de los contratos celebrados entre usuarios.",
    cguSection2Title: "2. Cláusula de no responsabilidad (P2P)",
    cguSection2Desc: "Los intercambios, intervenciones físicas y préstamos de material son responsabilidad exclusiva de las partes interesadas. Cada miembro se compromete a actuar con prudencia y diligencia.",
    cguSection3Title: "3. Protección de Datos y RGPD",
    cguSection3Desc: "Tus datos personales (nombre, correo, ciudad, habilidades) están estrictamente aislados en tu espacio seguro y nunca se venden a terceros.",
    acceptCguAndPrivacy: "Acepto las Condiciones y la Política RGPD",
    cguModalTitle: "Términos y Condiciones y Carta Troco",
    cguModalSubtitle: "Versión 2026.1 • Compromiso comunitario y conformidad legal",
    cguTabSummary: "📋 Los 6 Pilares Fundamentales",
    cguTabFull: "📜 Texto Jurídico Completo",
    cguWelcomeIntro: "¡Bienvenido a Troco! Para garantizar una plataforma segura, justa y cálida, te invitamos a consultar y aprobar las siguientes normas.",
    pillar1Title: "1 Hora = 1 Ficha Troco",
    pillar1Desc: "La regla fundamental de Troco se basa en la igualdad del tiempo compartido. Una hora de ayuda o formación equivale siempre a 1 Ficha Troco, garantizando una economía colaborativa justa y descentralizada.",
    pillar2Title: "Seguridad de Préstamos y Fianzas",
    pillar2Desc: "Para cualquier préstamo de material, se puede solicitar una preautorización bancaria de fianza sin cobro inmediato, asegurando la devolución de los equipos en perfecto estado.",
    pillar3Title: "Tolerancia Cero Fraude y Estafas",
    pillar3Desc: "Están estrictamente prohibidos: cupones prepagados (Transcash, Neosurf), transferencias externas (Western Union), datos bancarios en texto claro y contenidos ilícitos.",
    pillar4Title: "Moderación y Sanciones",
    pillar4Desc: "Cualquier incumplimiento de las normas comunitarias puede provocar una suspensión temporal, Shadow-Ban o expulsión definitiva de la cuenta.",
    pillar5Title: "Protección RGPD y Datos",
    pillar5Desc: "Tus datos personales están cifrados (SSL/TLS 256 bits), nunca se venden y tienes derecho a acceso, portabilidad y supresión total en cualquier momento.",
    pillar6Title: "Cortesía y Respeto Mutuo",
    pillar6Desc: "Los intercambios, videollamadas y conversaciones deben desarrollarse en un ambiente respetuoso, puntual y cuidadoso con la privacidad.",
    cguArt1Title: "Artículo 1 — Objeto y Definición de la Plataforma",
    cguArt1Desc: "Troco es una plataforma digital de intermediación comunitaria que permite el trueque de habilidades, el préstamo de equipos entre particulares y el intercambio de servicios basado en la unidad de tiempo 'Ficha Troco' o condiciones acordadas mutuamente.",
    cguArt2Title: "Artículo 2 — Cuenta y Veracidad de la Información",
    cguArt2Desc: "El usuario se compromete a proporcionar información verídica en el registro, mantener su perfil actualizado y crear una única cuenta por persona física.",
    cguArt3Title: "Artículo 3 — Regla del Trueque Temporal y Monetización",
    cguArt3Desc: "La Ficha Troco representa 1 hora de servicio o formación. La compra de fichas o promociones es definitiva de conformidad con las leyes de consumo aplicables.",
    cguArt4Title: "Artículo 4 — Fianzas y Responsabilidad de Préstamos",
    cguArt4Desc: "Las fianzas para préstamos de material constituyen una garantía financiera preautorizada. En caso de no devolución o daño comprobado, el importe podrá ser cargado tras revisión del equipo de mediación.",
    cguArt5Title: "Artículo 5 — Moderación, Detección y Sanciones",
    cguArt5Desc: "Troco utiliza herramientas de análisis automatizado para detectar fraudes y contenidos ilícitos, reservándose el derecho de aplicar Shadow-Ban o suspender cuentas infractoras sin previo aviso.",
    cguArt6Title: "Artículo 6 — Datos Personales (RGPD)",
    cguArt6Desc: "Los datos se tratan conforme al RGPD (UE 2016/679). Cada usuario tiene derecho de acceso, rectificación, portabilidad y supresión a través de su Centro de Privacidad.",
    agreeTermsCheckbox: "He leído y acepto sin reservas las Condiciones Generales de Uso de Troco (Versión 2026.1).",
    agreePrivacyCheckbox: "Acepto la Política de Privacidad y el tratamiento de mis datos de conformidad con el RGPD.",
    acceptTermsButton: "Aceptar Condiciones y Unirse a la Comunidad",
