    cguConsentTitle: "Termini e Condizioni e GDPR",
    cguConsentSubtitle: "Quadro giuridico e impegno comunitario",
    cguSection1Title: "1. Piattaforma di intermediazione tecnica",
    cguSection1Desc: "Troco fornisce un'infrastruttura software che consente agli utenti di pubblicare annunci, scambiare servizi e comunicare. Troco non è parte dei contratti conclusi tra gli utenti.",
    cguSection2Title: "2. Clausola di esclusione di responsabilità (P2P)",
    cguSection2Desc: "Gli scambi, gli interventi fisici e i prestiti di materiale sono di esclusiva responsabilità delle parti interessate. Ciascun membro si impegna ad agire con prudenza e diligenza.",
    cguSection3Title: "3. Protezione dei Dati e GDPR",
    cguSection3Desc: "I tuoi dati personali (nome, email, città, competenze) sono rigorosamente isolati nel tuo spazio protetto e non vengono mai rivenduti a terzi.",
    acceptCguAndPrivacy: "Accetto i Termini e la Politica GDPR",
    cguModalTitle: "Termini e Condizioni e Statuto Troco",
    cguModalSubtitle: "Versione 2026.1 • Impegno comunitario e conformità legale",
    cguTabSummary: "📋 I 6 Pilastri Fondamentali",
    cguTabFull: "📜 Testo Giuridico Integrale",
    cguWelcomeIntro: "Benvenuto su Troco! Per garantire una piattaforma sicura, equa e accogliente, ti chiediamo di leggere e approvare le seguenti regole.",
    pillar1Title: "1 Ora = 1 Gettone Troco",
    pillar1Desc: "La regola fondamentale di Troco si basa sulla parità del tempo condiviso. Un'ora di aiuto o formazione equivale sempre a 1 Gettone Troco, garantendo un'economia collaborativa equa e decentralizzata.",
    pillar2Title: "Sicurezza dei Prestiti e Cauzioni",
    pillar2Desc: "Per ogni prestito di materiale, può essere richiesta una pre-autorizzazione cauzionale senza addebito immediato, garantendo la restituzione in perfetto stato.",
    pillar3Title: "Tolleranza Zero Frodi e Truffe",
    pillar3Desc: "Sono severamente vietati: coupon prepagati (Transcash, Neosurf), bonifici esterni (Western Union), dati bancari in chiaro e contenuti illeciti.",
    pillar4Title: "Moderazione e Sanzioni",
    pillar4Desc: "Qualsiasi violazione delle regole della community può comportare una sospensione temporanea, Shadow-Ban o ban definitivo dell'account.",
    pillar5Title: "Protezione GDPR e Dati",
    pillar5Desc: "I tuoi dati sono protetti da crittografia (SSL/TLS 256 bit), non vengono mai venduti e hai diritto di accesso, portabilità e cancellazione in ogni momento.",
    pillar6Title: "Cortesia e Rispetto Reciproco",
    pillar6Desc: "Gli scambi, le videochiamate e i messaggi devono svolgersi in un clima cordiale, puntuale e rispettoso della privacy di ciascuno.",
    cguArt1Title: "Articolo 1 — Oggetto e Definizione della Piattaforma",
    cguArt1Desc: "Troco è una piattaforma digitale di intermediazione che consente lo scambio di competenze, il prestito di attrezzature tra privati e lo scambio di servizi basato sull'unità temporale 'Gettone Troco' o su accordi reciproci.",
    cguArt2Title: "Articolo 2 — Account e Accuratezza delle Informazioni",
    cguArt2Desc: "L'utente si impegna a fornire informazioni veritiere durante la registrazione, mantenere aggiornato il profilo e creare un solo account per persona fisica.",
    cguArt3Title: "Articolo 3 — Regola del Baratto Temporale e Monetizzazione",
    cguArt3Desc: "Il Gettone Troco rappresenta 1 ora di servizio o formazione. L'acquisto di gettoni o boost di visibilità è definitivo conformemente alle normative a tutela del consumatore.",
    cguArt4Title: "Articolo 4 — Cauzioni e Responsabilità dei Prestiti",
    cguArt4Desc: "Le cauzioni per il prestito di beni materiali costituiscono una garanzia finanziaria pre-autorizzata. In caso di mancata restituzione o danni verificati, l'importo potrà essere addebitato previa mediazione Troco.",
    cguArt5Title: "Articolo 5 — Moderazione, Rilevamento e Sanzioni",
    cguArt5Desc: "Troco utilizza sistemi automatizzati per rilevare frodi e contenuti illeciti, riservandosi il diritto di applicare Shadow-Ban o sospendere gli account inadempienti.",
    cguArt6Title: "Articolo 6 — Dati Personali (GDPR)",
    cguArt6Desc: "I dati sono trattati in conformità al GDPR (UE 2016/679). Ciascun utente dispone del diritto di accesso, rettifica, portabilità e cancellazione tramite il proprio Centro Privacy.",
    agreeTermsCheckbox: "Ho letto e accetto senza riserve i Termini e Condizioni di Troco (Versione 2026.1).",
    agreePrivacyCheckbox: "Accetto l'Informativa sulla Privacy e il trattamento dei miei dati in conformità con il GDPR.",
    acceptTermsButton: "Accetta Termini ed Entra nella Community",
