    legalTexts: "Rechtstexte",
    cguConsentTitle: "AGB & DSGVO",
    cguConsentSubtitle: "Rechtlicher Rahmen und Gemeinschaftsverpflichtung",
    cguSection1Title: "1. Technische Vermittlungsplattform",
    cguSection1Desc: "Troco stellt eine Software-Infrastruktur bereit, die es Nutzern ermöglicht, Anzeigen zu veröffentlichen, Dienste auszutauschen und zu kommunizieren. Troco ist nicht Partei der zwischen Nutzern geschlossenen Verträge.",
    cguSection2Title: "2. Haftungsausschlussklausel (P2P)",
    cguSection2Desc: "Tauschgeschäfte, physische Einsätze und Geräteausleihen liegen in der ausschließlichen Verantwortung der beteiligten Parteien. Jedes Mitglied verpflichtet sich zur gebotenen Sorgfalt.",
    cguSection3Title: "3. Datenschutz & DSGVO",
    cguSection3Desc: "Ihre personenbezogenen Daten (Name, E-Mail, Stadt, Fähigkeiten) sind in Ihrem sicheren Bereich streng isoliert und werden niemals an Dritte verkauft.",
    acceptCguAndPrivacy: "Ich akzeptiere die AGB und die DSGVO-Richtlinie",
    cguModalTitle: "AGB & Troco-Charta",
    cguModalSubtitle: "Version 2026.1 • Gemeinschaftsengagement & Rechtskonformität",
    cguTabSummary: "📋 Die 6 Grundpfeiler",
    cguTabFull: "📜 Vollständiger Rechtstext",
    cguWelcomeIntro: "Willkommen bei Troco! Um eine sichere, faire und herzliche Plattform zu gewährleisten, bitten wir Sie, die folgenden Regeln zu lesen und zu bestätigen.",
    pillar1Title: "1 Stunde = 1 Troco-Token",
    pillar1Desc: "Die Grundregel von Troco basiert auf der Gleichwertigkeit geteilter Zeit. Eine Stunde Hilfe oder Schulung entspricht immer 1 Troco-Token, was eine faire und dezentrale Wirtschaft sichert.",
    pillar2Title: "Sicherheit bei Verleih & Kautionen",
    pillar2Desc: "Für jeden Geräteverleih kann eine Vorautorisierung als Kaution ohne sofortige Abbuchung verlangt werden, um eine einwandfreie Rückgabe sicherzustellen.",
    pillar3Title: "Null-Toleranz bei Betrug",
    pillar3Desc: "Streng verboten sind: Prepaid-Gutscheine (Transcash, Neosurf), externe Überweisungen (Western Union), Bankdaten im Klartext und illegale Inhalte.",
    pillar4Title: "Moderation & Sanktionen",
    pillar4Desc: "Verstöße gegen die Gemeinschaftsregeln können zu vorübergehender Sperrung, Shadow-Ban oder dauerhafter Kontolöschung führen.",
    pillar5Title: "DSGVO & Datenschutz",
    pillar5Desc: "Ihre Daten werden verschlüsselt (256-Bit SSL/TLS), niemals weiterverkauft, und Sie haben jederzeit das Recht auf Auskunft, Datenübertragbarkeit und vollständige Löschung.",
    pillar6Title: "Höflichkeit & Gegenseitiger Respekt",
    pillar6Desc: "Tauschvorgänge, Videokonferenzen und Chats müssen in einem wohlwollenden, pünktlichen und die Privatsphäre respektierenden Rahmen stattfinden.",
    cguArt1Title: "Artikel 1 — Gegenstand & Definition der Plattform",
    cguArt1Desc: "Troco ist eine digitale Plattform zur Vermittlung von Fähigkeiten, Geräten und Dienstleistungen auf Basis der Zeiteinheit 'Troco-Token' oder einvernehmlich vereinbarter Gegenleistungen.",
    cguArt2Title: "Artikel 2 — Konto & Richtigkeit der Angaben",
    cguArt2Desc: "Der Nutzer verpflichtet sich, bei der Registrierung korrekte Angaben zu machen, sein Profil aktuell zu halten und nur ein Konto pro Person anzulegen.",
    cguArt3Title: "Artikel 3 — Zeit-Tausch-Regeln & Monetarisierung",
    cguArt3Desc: "Der Troco-Token repräsentiert 1 Stunde Service oder Schulung. Käufe von Tokens oder Sichtbarkeits-Boosts sind endgültig und nicht erstattungsfähig.",
    cguArt4Title: "Artikel 4 — Kautionen & Haftung beim Verleih",
    cguArt4Desc: "Kautionen für den Materialverleih stellen eine vorautorisierte Sicherheitsgarantie dar. Bei Nichtrückgabe oder Beschädigung kann der Betrag nach Überprüfung durch das Troco-Team eingezogen werden.",
    cguArt5Title: "Artikel 5 — Moderation, Betrugserkennung & Sanktionen",
    cguArt5Desc: "Troco nutzt automatisierte Analysetools, um Betrug und verwerfliche Inhalte zu erkennen. Die Plattform behält sich das Recht vor, Shadow-Bans zu verhängen oder Konten fristlos zu sperren.",
    cguArt6Title: "Artikel 6 — Personenbezogene Daten (DSGVO)",
    cguArt6Desc: "Die Datenverarbeitung erfolgt streng nach DSGVO (EU 2016/679). Jeder Nutzer hat das Recht auf Auskunft, Berichtigung, Datenübertragbarkeit und Löschung über sein Datenschutzzentrum.",
    agreeTermsCheckbox: "Ich habe die Allgemeinen Nutzungsbedingungen von Troco (Version 2026.1) gelesen und akzeptiere sie vorbehaltlos.",
    agreePrivacyCheckbox: "Ich stimme der Datenschutzerklärung und der Verarbeitung meiner Daten gemäß DSGVO zu.",
    acceptTermsButton: "AGB akzeptieren & der Community beitreten",
    privacyCenterSubtitle: "Verwalten Sie Ihre persönlichen Daten und Datenschutzeinstellungen",
