    cguWelcomeIntro: "Trocoへようこそ！安全で公平かつ快適なプラットフォームを維持するため、以下の利用規約をご確認のうえ同意をお願いいたします。",
    pillar1Title: "1時間＝1 Troco トークン",
    pillar1Desc: "Trocoの根本理念は、共有される時間の公平性にあります。1時間の支援やレッスンは常に1 Troco トークンに換算され、公平で分散型の協同経済を保証します。",
    pillar2Title: "機材貸出の安全性と保証金",
    pillar2Desc: "機材の貸出時には、即時請求を行わない事前認証による保証金デポジットを設定でき、機材の完全な状態での返却を保護します。",
    pillar3Title: "詐欺・不正の完全禁止",
    pillar3Desc: "プリペイドカード、外部送金要請、平文での口座情報送信、違法コンテンツ、ヘイトスピーチは一切禁止されています。",
    pillar4Title: "モデレーションと制裁",
    pillar4Desc: "コミュニティ規範に違反した場合、一時停止、シャドウバン（出品の非表示化）、またはアカウントの永久停止措置が適用されます。",
    pillar5Title: "GDPRと個人情報保護",
    pillar5Desc: "個人データはSSL/TLS 256ビットで暗号化され第三者に販売されることはなく、閲覧・ポータビリティ・完全消去の権利を常に保持します。",
    pillar6Title: "礼儀と相互尊重",
    pillar6Desc: "取引、ビデオ通話、メッセージは、親切で時間通り、かつお互いのプライバシーを尊重した環境で行われる必要があります。",
    cguArt1Title: "第1条 — 本プラットフォームの目的と定義",
    cguArt1Desc: "Trocoは、時間の単位「Troco トークン」または双方の合意に基づき、スキルの交換、個人間での機材の貸出、サービスの相互提供を可能にするデジタルコミュニティ仲介プラットフォームです。",
    cguArt2Title: "第2条 — アカウントと登録情報の正確性",
    cguArt2Desc: "ユーザーは登録時に正確な情報を提供し、プロフィールを最新に保ち、1名につき1つのアカウントのみを作成することに同意します。",
    cguArt3Title: "第3条 — 時間交換ルールと収益化",
    cguArt3Desc: "Troco トークンは1時間のサービスまたはレッスンを表します。トークンの購入や出品ブーストは確定的なものであり、消費者規定に基づき返金不可です。",
    cguArt4Title: "第4条 — 保証金と機材貸出の責任",
    cguArt4Desc: "機材貸出時に設定される保証金は事前承認された保証枠です。未返却または破損が確認された場合、Troco仲裁チームの調査を経て請求が行われる場合があります。",
    cguArt5Title: "第5条 — 監視・不正検知と制裁",
    cguArt5Desc: "Trocoは自動検知ツールを用いて詐欺や不適切なコンテンツを検出します。違反が認められたアカウントには事前の通知なくシャドウバンや停止措置を講じる権利を有します。",
    cguArt6Title: "第6条 — 個人情報保護（GDPR）",
    cguArt6Desc: "データはGDPR（EU 2016/679）に厳格に準拠して処理されます。各ユーザーはプライバシーセンターを通じて、アクセス、訂正、データ移行、消去の権利を行使できます。",
